#include <string>
#include <vector>

using World = std::vector<std::string>;

int liveNeighbours(const World& world, int row, int column)
{
    const int rows{ static_cast<int>(world.size()) };
    const int cols{ static_cast<int>(world[0].size()) };
    int count{ 0 };
    for (int dr{ -1 }; dr <= 1; ++dr)
    {
        for (int dc{ -1 }; dc <= 1; ++dc)
        {
            if (dr == 0 && dc == 0)
            {
                continue;
            }
            const int r{ row + dr };
            const int c{ column + dc };
            if (r >= 0 && r < rows && c >= 0 && c < cols && world[static_cast<std::size_t>(r)][static_cast<std::size_t>(c)] == '#')
            {
                ++count;
            }
        }
    }
    return count;
}

World step(const World& world)
{
    World next{ world };
    for (std::size_t r{ 0 }; r < world.size(); ++r)
    {
        for (std::size_t c{ 0 }; c < world[r].size(); ++c)
        {
            const int n{ liveNeighbours(world, static_cast<int>(r), static_cast<int>(c)) };
            const bool alive{ world[r][c] == '#' };
            next[r][c] = (alive && (n == 2 || n == 3)) || (!alive && n == 3) ? '#' : '.';
        }
    }
    return next;
}

unitTests:
TEST("liveNeighbours in the middle") { const World w{ "###", "#.#", "###" }; CHECK_EQ(liveNeighbours(w, 1, 1), 8); }
TEST("liveNeighbours at corners and edges") { const World w{ "##.", "#..", "..." }; CHECK_EQ(liveNeighbours(w, 0, 0), 2); CHECK_EQ(liveNeighbours(w, 2, 2), 0); CHECK_EQ(liveNeighbours(w, 1, 1), 3); }
TEST("a block stays still") { const World w{ "....", ".##.", ".##.", "...." }; CHECK_EQ(step(w), w); }
TEST("a blinker flips") { const World a{ ".....", "..#..", "..#..", "..#..", "....." }; const World b{ ".....", ".....", ".###.", ".....", "....." }; CHECK_EQ(step(a), b); CHECK_EQ(step(b), a); }
TEST("a lonely cell dies") { CHECK_EQ(step(World{ "...", ".#.", "..." }), (World{ "...", "...", "..." })); }

